

const _savedScannerTf=localStorage.getItem('PMA_SCANNER_TF');if(!localStorage.getItem('PMA_SCANNER_DEFAULT_V2')){localStorage.setItem('PMA_SCANNER_TF','15m');localStorage.setItem('PMA_SCANNER_DEFAULT_V2','1')}const state={user:null,page:localStorage.getItem('PMA_CURRENT_PAGE')||'home',market:localStorage.getItem('PMA_MARKET')||'Forex',symbol:localStorage.getItem('PMA_SYMBOL')||'EURUSD',ref:new URLSearchParams(location.search).get('ref')||'',notif:[],scannerTimer:null,entryTimer:null,dayTradeTimer:null,notifTimer:null,browserAlertsReady:false,serverVerified:false,privateConversationId:null,restoringReload:false,notificationCategory:'All',scannerStyle:localStorage.getItem('PMA_SCANNER_STYLE')||'Scalping',scannerTf:localStorage.getItem('PMA_SCANNER_TF')||'15m',scannerLock:null,lastTrends:null};
const markets={Forex:['EURUSD','GBPUSD','USDJPY','GBPJPY','AUDUSD','USDCAD','USDCHF','NZDUSD','EURJPY','EURGBP','EURCHF','GBPCHF','AUDJPY','CADJPY'],Indices:['US30','NAS100','SPX500','GER40','UK100','FRA40','JP225'],Metals:['XAUUSD','XAGUSD','XPTUSD','XPDUSD'],Crypto:['BTCUSD','ETHUSD','SOLUSD','XRPUSD','LTCUSD'],Commodities:['USOIL','UKOIL','NATGAS','COPPER']};
const API_BASE=(localStorage.getItem('PMA_API_BASE')||(location.hostname==='127.0.0.1'||location.hostname==='localhost'?'http://127.0.0.1:8000':'https://pips-master-frontend.onrender.com')).replace(/\/$/,'');
async function api(path,opts={}){const headers={'Content-Type':'application/json',...(opts.headers||{})};const token=localStorage.getItem('PMA_TOKEN');if(token)headers.Authorization='Bearer '+token;const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),8000);try{const r=await fetch(API_BASE+'/api'+path,{...opts,headers,signal:controller.signal,cache:'no-store'});const x=await r.json().catch(()=>({}));if(!r.ok)throw Error(x.detail||'Request failed');return x}catch(e){if(e?.name==='AbortError')throw Error('Please try again in a moment.');if(e instanceof TypeError)throw Error('Please try again in a moment.');throw e}finally{clearTimeout(timer)}}
async function apiFast(path,opts={}){const headers={'Content-Type':'application/json',...(opts.headers||{})};const token=localStorage.getItem('PMA_TOKEN');if(token)headers.Authorization='Bearer '+token;const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),8000);try{const r=await fetch(API_BASE+'/api'+path,{...opts,headers,signal:controller.signal,cache:'no-store'});const x=await r.json().catch(()=>({}));if(!r.ok)throw Error(x.detail||'Request failed');return x}catch(e){throw e}finally{clearTimeout(timer)}}

