function urlBase64ToUint8Array(base64String){const padding='='.repeat((4-base64String.length%4)%4);const base64=(base64String+padding).replace(/-/g,'+').replace(/_/g,'/');const raw=atob(base64);return Uint8Array.from([...raw].map(c=>c.charCodeAt(0)))}
async function registerPushNotifications(){if(!state.user||!('serviceWorker' in navigator)||!('PushManager' in window)||!('Notification' in window)||Notification.permission!=='granted')return false;try{const reg=await navigator.serviceWorker.register('/sw.js');await navigator.serviceWorker.ready;let sub=await reg.pushManager.getSubscription();if(!sub){const key=PMA_VAPID_PUBLIC_KEY;sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:urlBase64ToUint8Array(key)})}const j=sub.toJSON();await apiFast('/push/subscribe',{method:'POST',body:JSON.stringify({endpoint:j.endpoint,keys:j.keys})});return true}catch(e){return false}}
function prefetchDayTradeCaches(){if(!state.user)return;const tf=state.dayTf||localStorage.getItem('PMA_DAY_TF')||'15m';const ordered=[state.market,...Object.keys(markets).filter(m=>m!==state.market)];ordered.forEach((m,i)=>{setTimeout(()=>{const key='PMA_DAYTRADE_'+m+'_'+tf;const symbols=markets[m].slice(0,6).join(',');apiFast('/day-trade/plan?market='+encodeURIComponent(m)+'&symbols='+encodeURIComponent(symbols)+'&timeframe='+encodeURIComponent(tf)).then(x=>localStorage.setItem(key,JSON.stringify(x))).catch(()=>{})},i*500)})}
function fastCached(key){return readJson('PMA_FAST_'+key,null)}
function saveFastCached(key,value){try{localStorage.setItem('PMA_FAST_'+key,JSON.stringify(value))}catch(e){}}
function ensureOnlineAccess(){if(navigator.onLine!==false)return true;showOfflineGate();return false}
function showOfflineGate(){let gate=document.getElementById('offlineGate');if(!gate){gate=document.createElement('div');gate.id='offlineGate';gate.innerHTML='<div class="offline-card"><div class="offline-icon">⌁</div><h2>No internet connection</h2><p>Connect to the internet to continue using Pips Master Academy.</p><button class="btn" onclick="retryOnlineAccess()">Retry</button></div>';document.body.appendChild(gate)}gate.classList.add('show')}
function hideOfflineGate(){document.getElementById('offlineGate')?.classList.remove('show')}
function retryOnlineAccess(){if(navigator.onLine===false){showOfflineGate();return}hideOfflineGate();softRefreshCurrentPage()}
window.addEventListener('offline',showOfflineGate);window.addEventListener('online',hideOfflineGate);
function show(id){if(id==='login'){localStorage.removeItem('PMA_TOKEN');state.user=null;state.serverVerified=false;liEmail.value='';liPass.value='';liMsg.textContent='';}document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));document.getElementById(id).classList.add('active');if(id==='signup'&&state.ref){suMsg.textContent='Referral code: '+state.ref;suMsg.className='form-msg ok'}if(id==='app')page(state.page||'home',true)}
function applyTheme(){const theme=localStorage.getItem('PMA_THEME')||'dark';document.body.classList.toggle('light',theme==='light');const b=document.getElementById('themeToggle');if(b){b.innerHTML=theme==='light'?'<span class="theme-icon" aria-hidden="true">☀️</span><span>Light mode</span>':'<span class="theme-icon" aria-hidden="true">🌙</span><span>Dark mode</span>';b.setAttribute('aria-label','Switch to '+(theme==='light'?'dark':'light')+' mode');}}
function toggleTheme(){const next=(localStorage.getItem('PMA_THEME')||'dark')==='light'?'dark':'light';localStorage.setItem('PMA_THEME',next);applyTheme()}

function togglePassword(id,btn){const el=document.getElementById(id);el.type=el.type==='password'?'text':'password';btn.textContent=el.type==='password'?'👁️':'🙈'}
function validateSignup(){if(!document.getElementById('suPass'))return;const p=suPass.value,p2=suPass2.value;suPassMsg.textContent=p.length===0?'':'Password must be at least 8 characters.';suPassMsg.className='form-msg '+(p.length>=8?'ok':'error');suMatchMsg.textContent=p2.length===0?'':(p===p2?'Passwords match.':'Passwords do not match.');suMatchMsg.className='form-msg '+(p2.length===0?'':(p===p2?'ok':'error'))}
function saveLocalUser(u){localStorage.setItem('PMA_LOCAL_USER',JSON.stringify(u));state.user=u;localStorage.setItem('PMA_USER_PROFILE',JSON.stringify(u))}
function readJson(key,fallback=[]){try{return JSON.parse(localStorage.getItem(key)||JSON.stringify(fallback))}catch{return fallback}}
function addNotification(title,text,type='info',targetPage=''){const n={id:Date.now()+Math.random(),title,text,type,target_page:targetPage||notificationTarget({type}),time:new Date().toLocaleString(),read:false};const history=readJson('PMA_NOTIFICATION_HISTORY',[]);history.unshift(n);localStorage.setItem('PMA_NOTIFICATION_HISTORY',JSON.stringify(history.slice(0,250)));const inbox=readJson('PMA_NOTIFICATION_INBOX',[]);inbox.unshift(n);localStorage.setItem('PMA_NOTIFICATION_INBOX',JSON.stringify(inbox.slice(0,60)));state.notif=history;updateNotifBadge()}
function migrateNotifications(){const old=readJson('PMA_NOTIFICATIONS',[]);if(old.length&&!localStorage.getItem('PMA_NOTIFICATION_HISTORY')){localStorage.setItem('PMA_NOTIFICATION_HISTORY',JSON.stringify(old));localStorage.setItem('PMA_NOTIFICATION_INBOX',JSON.stringify(old));}}
function getNotificationHistory(){migrateNotifications();return readJson('PMA_NOTIFICATION_HISTORY',[])}
function getNotificationInbox(){migrateNotifications();return readJson('PMA_NOTIFICATION_INBOX',[])}
function updateNotifBadge(){const dismissed=new Set(readJson('PMA_NOTIFICATION_DISMISSED_IDS',[]).map(String));const n=getNotificationHistory().filter(x=>!dismissed.has(String(x.server_id||x.id))&&!x.read);const b=document.getElementById('notifBadge');if(b)b.textContent=String(n.length)}
function loadLocalUser(){try{return JSON.parse(localStorage.getItem('PMA_LOCAL_USER')||'null')}catch{return null}}
async function signup(){validateSignup();if(!suUser.value.trim()||!suName.value.trim()||!suEmail.value.trim()){suMsg.textContent='Please complete all required fields.';suMsg.className='form-msg error';return}if(suPass.value.length<8||suPass.value!==suPass2.value){suMsg.textContent=suPass.value!==suPass2.value?'Passwords do not match.':'Please fix the password above.';suMsg.className='form-msg error';return}suMsg.textContent='Creating your account…';suMsg.className='form-msg ok';try{const x=await apiRetry('/auth/signup',{method:'POST',body:JSON.stringify({username:suUser.value,full_name:suName.value,email:suEmail.value.trim().toLowerCase(),password:suPass.value,confirm_password:suPass2.value,referral:state.ref})},2);localStorage.removeItem('PMA_TOKEN');state.user=null;state.serverVerified=false;show('login');liEmail.value=suEmail.value.trim().toLowerCase();liPass.value='';liMsg.textContent='Account created successfully. Enter your password to sign in.';liMsg.className='form-msg ok';suMsg.textContent='Account created. Please log in with your email and password.';suMsg.className='form-msg ok'}catch(e){suMsg.textContent=e?.message||'The PMA server could not create your account. Please try again.';suMsg.className='form-msg error'}}
async function login(){const email=liEmail.value.trim().toLowerCase(),pass=liPass.value;if(!email||!pass){liMsg.textContent='Enter your email and password.';liMsg.className='form-msg error';return}liMsg.textContent='';liMsg.className='form-msg';try{const x=await apiRetry('/auth/login',{method:'POST',body:JSON.stringify({email,password:pass})},2);state.user=x.user;state.serverVerified=true;localStorage.setItem('PMA_TOKEN',x.token||'');saveLocalUser(x.user);addNotification('Welcome back','You successfully logged in.','security');enterApp(true);return}catch(e){liMsg.textContent=e?.message||'Login failed. Check your email and password, then try again.';liMsg.className='form-msg error'}}
function apiRetry(path,opts={},retries=1){let attempt=0;const run=()=>api(path,opts).catch(e=>{if(attempt++<retries)return new Promise(r=>setTimeout(r,700)).then(run);throw e});return run()}
async function warmBackend(){try{await fetch(API_BASE+'/api/health',{cache:'no-store',keepalive:true})}catch(e){}}
function enterApp(resetPage=false){warmBackend();show('app');userMini.textContent='@'+state.user.username;if(resetPage){state.page='home';localStorage.setItem('PMA_CURRENT_PAGE','home');localStorage.removeItem('PMA_SCROLL_HOME')}page(state.page||'home',!resetPage);syncBackendProfile();syncBackendNotifications();if('Notification' in window&&Notification.permission==='granted')registerPushNotifications();startNotificationPolling();setTimeout(prefetchDayTradeCaches,50)}
function closeMenu(){document.getElementById('side').classList.remove('open')}
function animatePage(){const root=document.getElementById('screen');if(!root)return;const items=root.querySelectorAll('.card,.section-title,.lead,.photo-section,.grid,.grid3,.feature-grid');items.forEach((el,i)=>{el.classList.add('reveal');el.style.setProperty('--reveal-delay',Math.min(i*35,350)+'ms');el.dataset.anim=(i%3===0?'left':i%3===1?'up':'right')});const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('reveal-in');io.unobserve(e.target)}}),{threshold:.08});items.forEach(el=>io.observe(el))}
function page(p,restore=false){if(!ensureOnlineAccess())return;if(p==='admin')p='profile';if(state.page&&state.page!==p){const old=document.getElementById('screen');if(old)localStorage.setItem('PMA_SCROLL_'+state.page,String(old.scrollTop||0))}state.page=p;localStorage.setItem('PMA_CURRENT_PAGE',p);localStorage.setItem('PMA_MARKET',state.market);localStorage.setItem('PMA_SYMBOL',state.symbol);closeMenu();pageTitle.textContent=p==='profile'?'My Profile':p[0].toUpperCase()+p.slice(1);const s=document.getElementById('screen');const views={home,signals,daytrade,calculator,progress,referrals,community,messages,history,profile,feedback,notifications,about};s.innerHTML=(views[p]||home)();if(p==='calculator')setCalcTab('risk');if(state.page!=='signals')clearInterval(state.scannerTimer);if(state.page!=='daytrade')clearInterval(state.dayTradeTimer);if(p==='signals')startScanner();if(p==='daytrade')startDayTrade();if(p==='home'){loadHomeProgress();startMindsetCarousel();}if(p==='progress')loadProgress();if(p==='referrals')loadReferrals();if(p==='community')loadCommunity();if(p==='messages')loadPrivateMessagesPage();if(p==='profile'&&state.serverVerified&&state.user?.role==='admin')requestAnimationFrame(loadAdminStats);if(p==='feedback')loadMyFeedback();if(p==='notifications')loadNotificationsPage();if(p==='history')loadTradingHistoryPage();if(p==='about')loadFeedbackSummary();requestAnimationFrame(()=>{s.scrollTop=restore?Number(localStorage.getItem('PMA_SCROLL_'+p)||0):0;animatePage()})}
async function loadHomeProgress(){
  const cached=readJson('PMA_PROGRESS_CACHE',null);
  const apply=(p)=>{if(!p)return;const a=document.getElementById('homeRank'),b=document.getElementById('homeLearning'),c=document.getElementById('homeReferral'),d=document.getElementById('homeOverall');const as=document.getElementById('homeRankSub'),bs=document.getElementById('homeLearningSub'),cs=document.getElementById('homeReferralSub'),ds=document.getElementById('homeOverallSub');if(a)a.textContent=p.rank||'—';if(b)b.textContent=(p.learning_progress??0)+'%';if(c)c.textContent=p.qualified_referrals_this_month??0;if(d)d.textContent=(p.overall_progress??0)+'%';if(as)as.textContent=p.xp!=null?`${p.xp} XP`:'';if(bs)bs.textContent=`${p.completed_lessons||0}/${p.total_lessons||0} lessons`;if(cs)cs.textContent='This month';if(ds)ds.textContent='Academy progress'};
  apply(cached);
  try{const p=await api('/progress');localStorage.setItem('PMA_PROGRESS_CACHE',JSON.stringify(p));apply(p)}catch(e){/* cached values remain visible */}
}
